sys_script_include.script:
var Ikkatusinsei = Class.create();
Ikkatusinsei.prototype = {
    initialize: function() {},

    ikkatu: function(sys_id, shubetu) {
        var errMsg = [];

        var att = new GlideRecord('sys_attachment');
        att.addQuery('table_sys_id', sys_id);
        att.addQuery('file_name', 'ENDSWITH', '申請書.xlsx');
        att.query();

        if (!att.next()) {
            return "添付無し";
        } else {
            var gsa = new GlideSysAttachment();
            var inputStream = gsa.getContentStream(att.getUniqueValue());

            var parser = new sn_impex.GlideExcelParser(); // .xlsx 専用
            parser.setNullToEmpty(true);
            parser.setSource(inputStream);
            var sheetNames = parser.getSheetNames();
            if (sheetNames && sheetNames.length > 0) {
                parser.setSheetName(sheetNames[0]);
            }
            if (!parser.parse()) {
                gs.addErrorMessage(parser.getErrorMessage() || 'Excel parse failed.');
                current.setAbortAction(true);
            }

            var headers = parser.getColumnHeaders();

            // --- 5行目まで進める ---
            var targetExcelRow = 5; // Excel 行番号
            var dataRowAdvance = targetExcelRow - 1; // 2行目=1, …, 6行目=5
            for (var i = 0; i < dataRowAdvance; i++) {
                if (!parser.next()) {
                    return "フォーマット違い";
                }
            }

            // ここで5行目に位置している想定
            var row = parser.getRow();

            var startIdx = 1; // B列
            var endIdx = 17; // R列
            var letters = ['B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L', 'M', 'N', 'O', 'P', 'Q', 'R'];
            var parts = [];

            for (var idx = startIdx; idx <= endIdx; idx++) {
                var letter = letters[idx - startIdx];
                var val = row[headers[idx]];
                val = val.replace(/[\s\u3000]+/g, '');
                parts.push(val);
            }

            var expectedHeaders = ['No.',
                '発令日', '氏名', '従業員番号', '新役位', '新職名', '新勤務地',
                '新職務等級', '新役割等級', '新VU区分',
                '旧役位', '旧職名', '旧勤務地', '旧職務等級', '旧役割等級', '旧VU区分', '備考'
            ];

            var x = [];
            var y = [];
            var z = [];
            var flg = false;

            for (var i = 0; i < expectedHeaders.length; i++) {
                if (parts[i] != expectedHeaders[i]) {
                    x.push(letters[i]);
                    y.push(parts[i]);
                    z.push(expectedHeaders[i]);
                    flg = true;
                    continue;
                }
            }

            if (flg != false) {
                for (var errCount = 0; errCount < x.length; errCount++) {
                    gs.addErrorMessage(att.file_name + "の" + x[errCount] + "5セルが「" + y[errCount] + "」になっています。正しくは「" + z[errCount] + "」です。");
                }
                return "フォーマット違い";
            }

            var count = 1;
            var nullCount = 0;

            while (true) {
                if (!parser.next()) {
                    break;
                }
                row = parser.getRow();
                startIdx = 1; // B列
                endIdx = 17; // R列
                parts = [];

                var noVal = row[headers[1]]; // B列（No.）
                if (gs.nil(noVal)) {
                    nullCount++;
                    if (nullCount >= 2) {
                        // 空白2行連続 → 終了
                        break;
                    } else {
                        // 空白1行だけ → スキップして次の行へ
                        continue;
                    }
                }

                var errFlg = false;
                for (var idx = startIdx; idx <= endIdx; idx++) {
                    if (errFlg == true) {
                        break;
                    }
                    var val = row[headers[idx]];

                    if (idx == 4) {
                        if (gs.nil(val)) {
                            errMsg.push(att.file_name + "の" +"No." + count + "は従業員番号が記入されていないため、処理をスキップしました。");
                            errFlg = true;
                            break;
                        } else {
                            var userSysId = this.serchUser(val);
                            if (userSysId == "NoHit") {
                                errMsg.push(att.file_name + "の" +"No." + count + "は記載の従業員番号で登録されているユーザーがいないため、処理をスキップしました。");
                                errFlg = true;
                                break;
                            } else {
                                parts.push(userSysId);
                                nullCount = 0;
                                continue;
                            }
                        }
                    }
                    parts.push(val);
                    nullCount = 0;
                }
                count++;
                if (errFlg == false) {
                    this.addMeisai(sys_id, parts, shubetu);
                }
            }
            parser.close();
        }
        for (var msgCount = 0; msgCount < errMsg.length; msgCount++) {
            gs.addInfoMessage(errMsg[msgCount]);
        }

        while (att.next()) {
            var gsa = new GlideSysAttachment();
            var inputStream = gsa.getContentStream(att.getUniqueValue());

            var parser = new sn_impex.GlideExcelParser(); // .xlsx 専用
            parser.setNullToEmpty(true);
            parser.setSource(inputStream);
            var sheetNames = parser.getSheetNames();
            if (sheetNames && sheetNames.length > 0) {
                parser.setSheetName(sheetNames[0]);
            }
            if (!parser.parse()) {
                gs.addErrorMessage(parser.getErrorMessage() || 'Excel parse failed.');
                current.setAbortAction(true);
            }

            var headers = parser.getColumnHeaders();

            // --- 5行目まで進める ---
            var targetExcelRow = 5; // Excel 行番号
            var dataRowAdvance = targetExcelRow - 1; // 2行目=1, …, 6行目=5
            for (var i = 0; i < dataRowAdvance; i++) {
                if (!parser.next()) {
                    return "フォーマット違い";
                }
            }

            // ここで5行目に位置している想定
            var row = parser.getRow();

            var startIdx = 1; // B列
            var endIdx = 17; // R列
            var letters = ['B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L', 'M', 'N', 'O', 'P', 'Q', 'R'];
            var parts = [];

            for (var idx = startIdx; idx <= endIdx; idx++) {
                var letter = letters[idx - startIdx];
                var val = row[headers[idx]];
                val = val.replace(/[\s\u3000]+/g, '');
                parts.push(val);
            }

            var expectedHeaders = ['No.',
                '発令日', '氏名', '従業員番号', '新役位', '新職名', '新勤務地',
                '新職務等級', '新役割等級', '新VU区分',
                '旧役位', '旧職名', '旧勤務地', '旧職務等級', '旧役割等級', '旧VU区分', '備考'
            ];

            var x = [];
            var y = [];
            var z = [];
            var flg = false;

            for (var i = 0; i < expectedHeaders.length; i++) {
                if (parts[i] != expectedHeaders[i]) {
                    x.push(letters[i]);
                    y.push(parts[i]);
                    z.push(expectedHeaders[i]);
                    flg = true;
                    continue;
                }
            }

            if (flg != false) {
                for (var errCount = 0; errCount < x.length; errCount++) {
                    gs.addErrorMessage(att.file_name + "の" +x[errCount] + "5セルが「" + y[errCount] + "」になっています。正しくは「" + z[errCount] + "」です。");
                }
                return "フォーマット違い";
            }

            var count = 1;
            var nullCount = 0;

            while (true) {
                if (!parser.next()) {
                    break;
                }
                row = parser.getRow();
                startIdx = 1; // B列
                endIdx = 17; // R列
                parts = [];

                var noVal = row[headers[1]]; // B列（No.）
                if (gs.nil(noVal)) {
                    nullCount++;
                    if (nullCount >= 2) {
                        // 空白2行連続 → 終了
                        break;
                    } else {
                        // 空白1行だけ → スキップして次の行へ
                        continue;
                    }
                }

                var errFlg = false;
                for (var idx = startIdx; idx <= endIdx; idx++) {
                    if (errFlg == true) {
                        break;
                    }
                    var val = row[headers[idx]];

                    if (idx == 4) {
                        if (gs.nil(val)) {
                            errMsg.push(att.file_name + "の" +"No." + count + "は従業員番号が記入されていないため、処理をスキップしました。");
                            errFlg = true;
                            break;
                        } else {
                            var userSysId = this.serchUser(val);
                            if (userSysId == "NoHit") {
                                errMsg.push(att.file_name + "の" +"No." + count + "は記載の従業員番号で登録されているユーザーがいないため、処理をスキップしました。");
                                errFlg = true;
                                break;
                            } else {
                                parts.push(userSysId);
                                nullCount = 0;
                                continue;
                            }
                        }
                    }
                    parts.push(val);
                    nullCount = 0;
                }
                count++;
                if (errFlg == false) {
                    this.addMeisai(sys_id, parts, shubetu);
                }
            }
            parser.close();
        }

        for (var msgCount = 0; msgCount < errMsg.length; msgCount++) {
            gs.addInfoMessage(errMsg[msgCount]);
        }
        att.deleteMultiple();
        return "OK";
    },

    addMeisai: function(sys_id, parts, shubetu) {
        var gr = new GlideRecord('x_1882833_organi_0_meisai');
        gr.initialize();

        var gdt = parts[1];
        var gd = new GlideDate();
        gd.setValue(gdt);
        gr.hatureibi = gd;

        if (shubetu == 1) {
            shubetu = "gen";
        } else {
            shubetu = "exe";
        }
        gr.type = shubetu;
        gr.sinsei_number = sys_id;
        gr.name = parts[3]['sys_id'];
        gr.name_kanji = parts[3]['name'];
        gr.number = parts[3]['number'];
        gr.yakui_sin = parts[4];
        gr.kimuti_sin = parts[6];

        var ans = this.serchShozoku(parts[3]['sys_id']);
        if (ans != 'NoHit') {
            gr.yakui_kyuu = ans['yakui'];
        }

        gr.insert();

    },

    serchUser: function(number) {
        var user = [];
        var gr = new GlideRecord('sys_user');
        gr.addQuery('u_number', number);
        gr.query();

        if (gr.next()) {
            user.sys_id = gr.getValue('sys_id');
            user.name = gr.getValue('u_ukanji_name');
            user.number = number;
            return user;
        } else {
            return "NoHit";
        }

    },

    serchShozoku: function(sys_id) {
        var shozoku = [];
        var gr = new GlideRecord('x_1882833_organi_0_shozoku');
        gr.addQuery('user_id', sys_id);
        gr.query();

        if (gr.next()) {
            shozoku.yakui = gr.getValue('yakui');
            return shozoku;
        } else {
            return "NoHit";
        }

    },

    type: 'Ikkatusinsei'
};
